<?php
/** Read-only financial tables shared by live/frozen report presentation and print. */
const REPORT_COMPONENT_TITLES=['worksheet'=>'Monthly accounting worksheet','trial_balance'=>'Trial Balance','income_statement'=>'Income and expenses','financial_position'=>'Financial position','cash_flows'=>'Indirect cash flows','project_activity'=>'Project activity','advance_aging'=>'Advance aging','budget_actuals'=>'Budget versus actual'];
function report_view_escape($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function report_view_money($v):string{return $v===null?'Unavailable':report_view_escape(accounting_money((string)$v));}
function report_view_table(array $rows,array $columns,string $label,?array $total=null):void
{
    ?><div class="fr-table-wrap" tabindex="0" role="region" aria-label="<?= report_view_escape($label) ?>"><table><caption class="rpt-caption"><?= report_view_escape($label) ?></caption><thead><tr><?php foreach($columns as [$key,$title,$kind]): ?><th<?= $kind==='money'?' class="fr-money"':'' ?>><?= report_view_escape($title) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($columns as $n=>[$key,$title,$kind]): $tag=$n===0?'th':'td'; ?><<?= $tag ?><?= $n===0?' scope="row"':'' ?><?= $kind==='money'?' class="fr-money"':'' ?>><?= $kind==='money'?report_view_money($row[$key]??null):report_view_escape($row[$key]??'') ?></<?= $tag ?>><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="<?= count($columns) ?>">No activity or balances in this report.</td></tr><?php endif; ?></tbody><?php if($total!==null): ?><tfoot><tr><?php foreach($columns as $n=>[$key,$title,$kind]): ?><td<?= $kind==='money'?' class="fr-money"':'' ?>><?= $n===0?'Total':($kind==='money'&&isset($total[$key])?report_view_money($total[$key]):'') ?></td><?php endforeach; ?></tr></tfoot><?php endif; ?></table></div><?php
}
function report_view_totals(array $values):void{?><dl class="fr-totals"><?php foreach($values as $title=>$value): ?><div><dt><?= report_view_escape($title) ?></dt><dd><?= report_view_money($value) ?></dd></div><?php endforeach; ?></dl><?php }
function report_component_render(string $name,array $data):void
{
    if(!isset(REPORT_COMPONENT_TITLES[$name]))throw new LogicException('Unknown report component.');$account=['account_name','Account','text'];
    if($name==='worksheet'){
        ?><p class="fr-help fr-no-print">Scroll across each table to see every financial column. The account name stays visible. Print uses separate readable landscape sections.</p><?php
        $first=[$account];foreach(['opening_debit'=>'Opening debit','opening_credit'=>'Opening credit','CRB_debit'=>'CRB debit','CRB_credit'=>'CRB credit','CDB_debit'=>'CDB debit','CDB_credit'=>'CDB credit','GJ_debit'=>'GJ debit','GJ_credit'=>'GJ credit','ending_debit'=>'Ending debit','ending_credit'=>'Ending credit'] as $key=>$label)$first[]=[$key,$label,'money'];report_view_table($data['rows'],$first,'Opening, originating books and ending balances (PHP)',$data['totals']);
        $second=[$account];foreach(['statement_debit'=>'Monthly result debit','statement_credit'=>'Monthly result credit','position_debit'=>'Position debit','position_credit'=>'Position credit','excluded_or_prior_result_bridge'=>'Prior / excluded result'] as $key=>$label)$second[]=[$key,$label,'money'];$rows=$data['rows'];$rows[]=array_merge(['account_name'=>'Independently derived results'],array_fill_keys(['statement_debit','statement_credit','position_debit','position_credit','excluded_or_prior_result_bridge'],'0.00'),$data['derived_results']);?><div class="rpt-worksheet-results"><?php report_view_table($rows,$second,'Monthly result and cutoff Financial Position columns (PHP)',$data['totals']); ?></div><?php
    }elseif($name==='trial_balance'){report_view_table($data['rows'],[$account,['ending_debit','Debit (PHP)','money'],['ending_credit','Credit (PHP)','money']],'Account balances at cutoff',['ending_debit'=>$data['total_debits'],'ending_credit'=>$data['total_credits']]);report_view_totals(['Difference'=>$data['difference']]);
    }elseif($name==='income_statement'||$name==='financial_position'){
        report_view_table($data['rows'],[['section','Section','text'],$account,['amount','Amount (PHP)','money']],REPORT_COMPONENT_TITLES[$name]);report_view_totals($name==='income_statement'?['Income'=>$data['income'],'Expenses'=>$data['expenses'],'Surplus / deficit'=>$data['surplus_deficit']]:['Assets'=>$data['assets'],'Liabilities'=>$data['liabilities'],'Posted equity'=>$data['posted_equity'],'Accumulated result not transferred'=>$data['unclosed_accumulated_result'],'Reconciliation difference'=>$data['difference']]);
    }elseif($name==='cash_flows'){
        $values=[];foreach(['opening_cash'=>'Opening configured cash','result'=>'Monthly surplus / deficit','noncash_adjustments'=>'Noncash adjustments','working_capital'=>'Working capital changes','reclassifications'=>'Reviewed reclassifications','operating'=>'Net operating cash flow','investing'=>'Net investing cash flow','financing'=>'Net financing cash flow','net_cash_flow'=>'Net cash change','closing_cash'=>'Closing configured cash','difference'=>'Reconciliation difference'] as $key=>$title)$values[$title]=$data[$key];report_view_totals($values);if($data['noncash_disclosures']){?><h3>Noncash investing / financing disclosures</h3><?php report_view_table($data['noncash_disclosures'],[['journal_id','Transaction','text'],['label','Description','text'],['amount','Amount (PHP)','money']],'Noncash movements; excluded from physical cash totals');} ?><details class="fr-no-print"><summary>Supporting transaction bridge</summary><?php report_view_table($data['transaction_bridge'],[['journal_id','Transaction','text'],['cash_change','Cash change','money'],['operating','Operating','money'],['investing','Investing','money'],['financing','Financing','money']],'Validated cash movements (PHP)'); ?></details><?php
    }elseif($name==='project_activity'){?><p class="fr-help">Journal line project tags determine activity. Organization operations is the untagged bucket. Project activity does not promise an independently balanced project ledger.</p><?php report_view_table($data,[['project_name','Project / operations','text'],$account,['debit','Debit (PHP)','money'],['credit','Credit (PHP)','money'],['recognized_expense','Recognized expense (PHP)','money']],'Monthly activity by actual project');
    }elseif($name==='advance_aging'){report_view_table($data,[['number','Advance','text'],['employee','Accountable employee','text'],['due_date','Deadline','text'],['settlement_status','Settlement state','text'],['released','Released','money'],['liquidated','Liquidated','money'],['returned','Returned','money'],['outstanding','Outstanding','money'],['aging_bucket','Aging','text']],'Advance aging at cutoff (PHP)');
    }elseif($name==='budget_actuals'){?><p><?= $data['approved']?'Effective approved revision '.report_view_escape($data['approved']['revision']):'No approved budget for this month; approved amounts are unavailable.' ?></p><p class="fr-help">Signed recognized expense; refunds reduce actual. Advance releases are assets, with costs recognized on liquidation.</p><?php $rows=$data['rows'];foreach($rows as &$r){$r['budget_state']=$r['approved_amount']===null?'No allocation':($r['overrun']?'Over allocation':'');$r['percentage']=$r['utilization']===null?'Unavailable':number_format($r['utilization'],2).'%';}unset($r);report_view_table($rows,[['account_label','Expense account','text'],['project_label','Project / operations','text'],['approved_amount','Approved (PHP)','money'],['actual','Actual (PHP)','money'],['remaining','Remaining (PHP)','money'],['percentage','Utilization','text'],['budget_state','Status','text']],'Approved budget versus actual',['approved_amount'=>$data['approved_total'],'actual'=>$data['actual_total'],'remaining'=>$data['remaining_total']]);}
}
